00035     public static function process()
00036     {
00037         global $bearsamppLang, $bearsamppBins;
00038 
00039         return TplApp::getMenuEnable($bearsamppLang->getValue(Lang::MARIADB), self::MENU, get_called_class(), $bearsamppBins->getMariadb()->isEnable());
