00055     public static function getMenuMariadb()
00056     {
00057         global $bearsamppBins, $bearsamppLang, $bearsamppTools;
00058         $resultItems = $resultActions = '';
00059 
00060         $isEnabled = $bearsamppBins->getMariadb()->isEnable();
00061 
00062         // Download
00063         $resultItems .= TplAestan::getItemLink( $bearsamppLang->getValue(Lang::DOWNLOAD_MORE),
00064             HttpClient::getWebsiteUrl('module/mariadb', '#releases'),
00065             false,
00066             TplAestan::GLYPH_BROWSER
00067         ) . PHP_EOL;
00068 
00069         // Enable
00070         $tplEnable = TplApp::getActionMulti(
00071             self::ACTION_ENABLE, array($isEnabled ? Config::DISABLED : Config::ENABLED),
00072             array($bearsamppLang->getValue(Lang::MENU_ENABLE), $isEnabled ? TplAestan::GLYPH_CHECK : ''),
00073             false, get_called_class()
00074         );
00075         $resultItems .= $tplEnable[TplApp::SECTION_CALL] . PHP_EOL;
00076         $resultActions .= $tplEnable[TplApp::SECTION_CONTENT] . PHP_EOL;
00077 
00078         if ($isEnabled) {
00079             $resultItems .= TplAestan::getItemSeparator() . PHP_EOL;
00080 
00081             // Versions
00082             $tplVersions = TplApp::getMenu($bearsamppLang->getValue(Lang::VERSIONS), self::MENU_VERSIONS, get_called_class());
00083             $resultItems .= $tplVersions[TplApp::SECTION_CALL] . PHP_EOL;
00084             $resultActions .= $tplVersions[TplApp::SECTION_CONTENT] . PHP_EOL;
00085 
00086             // Service
00087             $tplService = TplApp::getMenu($bearsamppLang->getValue(Lang::SERVICE), self::MENU_SERVICE, get_called_class());
00088             $resultItems .= $tplService[TplApp::SECTION_CALL] . PHP_EOL;
00089             $resultActions .= $tplService[TplApp::SECTION_CONTENT] . PHP_EOL;
00090 
00091             // Debug
00092             $tplDebug = TplApp::getMenu($bearsamppLang->getValue(Lang::DEBUG), self::MENU_DEBUG, get_called_class());
00093             $resultItems .= $tplDebug[TplApp::SECTION_CALL] . PHP_EOL;
00094             $resultActions .= $tplDebug[TplApp::SECTION_CONTENT];
00095 
00096             // Console
00097             $resultItems .= TplAestan::getItemPowerShell(
00098                 $bearsamppLang->getValue(Lang::CONSOLE),
00099                 TplAestan::GLYPH_POWERSHELL,
00100                 null, $bearsamppTools->getPowerShell()->getTabTitleMariadb(), Path::getModuleSymlinkPath($bearsamppBins->getMariadb()), null
00101             ) . PHP_EOL;
00102 
00103             // Conf
00104             $resultItems .= TplAestan::getItemNotepad(basename($bearsamppBins->getMariadb()->getConf()), $bearsamppBins->getMariadb()->getConf()) . PHP_EOL;
00105 
00106             // Errors log
00107             $resultItems .= TplAestan::getItemNotepad($bearsamppLang->getValue(Lang::MENU_ERROR_LOGS), $bearsamppBins->getMariadb()->getErrorLog()) . PHP_EOL;
00108         }
00109 
00110         return $resultItems . PHP_EOL . $resultActions;
00111     }
