00123     public static function getMenuMariadbVersions()
00124     {
00125         global $bearsamppBins;
00126         $items = '';
00127         $actions = '';
00128 
00129         foreach ($bearsamppBins->getMariadb()->getVersionList() as $version) {
00130             $tplSwitchMariadbVersion = TplApp::getActionMulti(
00131                 self::ACTION_SWITCH_VERSION, array($version),
00132                 array($version, $version == $bearsamppBins->getMariadb()->getVersion() ? TplAestan::GLYPH_CHECK : ''),
00133                 false, get_called_class()
00134             );
00135 
00136             // Item
00137             $items .= $tplSwitchMariadbVersion[TplApp::SECTION_CALL] . PHP_EOL;
00138 
00139             // Action
00140             $actions .= PHP_EOL . $tplSwitchMariadbVersion[TplApp::SECTION_CONTENT];
00141         }
00142 
00143         return $items . $actions;
00144     }
