00198     public static function getMenuMariadbService()
00199     {
00200         global $bearsamppLang, $bearsamppBins;
00201 
00202         $tplChangePort = TplApp::getActionMulti(
00203             self::ACTION_CHANGE_PORT, null,
00204             array($bearsamppLang->getValue(Lang::MENU_CHANGE_PORT), TplAestan::GLYPH_NETWORK),
00205             false, get_called_class()
00206         );
00207 
00208         $isInstalled = $bearsamppBins->getMariadb()->getService()->isInstalled();
00209 
00210         $result = TplAestan::getItemActionServiceStart($bearsamppBins->getMariadb()->getService()->getName()) . PHP_EOL .
00211             TplAestan::getItemActionServiceStop($bearsamppBins->getMariadb()->getService()->getName()) . PHP_EOL .
00212             TplAestan::getItemActionServiceRestart($bearsamppBins->getMariadb()->getService()->getName()) . PHP_EOL .
00213             TplAestan::getItemSeparator() . PHP_EOL .
00214             TplApp::getActionRun(
00215                 Action::CHECK_PORT, array($bearsamppBins->getMariadb()->getName(), $bearsamppBins->getMariadb()->getPort()),
00216                 array(sprintf($bearsamppLang->getValue(Lang::MENU_CHECK_PORT), $bearsamppBins->getMariadb()->getPort()), TplAestan::GLYPH_LIGHT)
00217             ) . PHP_EOL .
00218             $tplChangePort[TplApp::SECTION_CALL] . PHP_EOL;
00219 
00220         $tplChangeRootPwd = null;
00221         if ($isInstalled) {
00222             $tplChangeRootPwd = TplApp::getActionMulti(
00223                 self::ACTION_CHANGE_ROOT_PWD, null,
00224                 array($bearsamppLang->getValue(Lang::MENU_CHANGE_ROOT_PWD), TplAestan::GLYPH_PASSWORD),
00225                 !$isInstalled, get_called_class()
00226             );
00227 
00228             $result .= $tplChangeRootPwd[TplApp::SECTION_CALL] . PHP_EOL;
00229         }
00230 
00231         if (!$isInstalled) {
00232             $tplInstallService = TplApp::getActionMulti(
00233                 self::ACTION_INSTALL_SERVICE, null,
00234                 array($bearsamppLang->getValue(Lang::MENU_INSTALL_SERVICE), TplAestan::GLYPH_SERVICE_INSTALL),
00235                 $isInstalled, get_called_class()
00236             );
00237 
00238             $result .= $tplInstallService[TplApp::SECTION_CALL] . PHP_EOL . PHP_EOL .
00239             $tplInstallService[TplApp::SECTION_CONTENT] . PHP_EOL;
00240         } else {
00241             $tplRemoveService = TplApp::getActionMulti(
00242                 self::ACTION_REMOVE_SERVICE, null,
00243                 array($bearsamppLang->getValue(Lang::MENU_REMOVE_SERVICE), TplAestan::GLYPH_SERVICE_REMOVE),
00244                 !$isInstalled, get_called_class()
00245             );
00246 
00247             $result .= $tplRemoveService[TplApp::SECTION_CALL] . PHP_EOL . PHP_EOL .
00248             $tplRemoveService[TplApp::SECTION_CONTENT] . PHP_EOL;
00249         }
00250 
00251         $result .= $tplChangePort[TplApp::SECTION_CONTENT] . PHP_EOL .
00252             ($tplChangeRootPwd != null ? $tplChangeRootPwd[TplApp::SECTION_CONTENT] . PHP_EOL : '');
00253 
00254         return $result;
00255     }
